function(props) {
  // Main component function
  function BinanceP2POffersView(props) {
    const { data } = props;
    if (!data || !data.offers) return null;

    // Function to generate color from string (for trader reputation)
    function stringToColor(string, alpha = 1) {
      if (!string) return 'rgba(107, 119, 140, ' + alpha + ')';
      let hash = 0;
      for (let i = 0; i < string.length; i++) {
        hash = string.charCodeAt(i) + ((hash << 5) - hash);
      }
      const h = hash % 360;
      return `hsla(${h}, 70%, 50%, ${alpha})`;
    }

    // Link icon SVG
    function LinkIcon() {
      return React.createElement('svg', {
        width: '10',
        height: '10',
        viewBox: '0 0 16 16',
        fill: 'none',
        style: { color: '#64748b' }
      }, [
        React.createElement('path', {
          key: 'p1',
          d: 'M6.5 9.5L9.5 6.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p2',
          d: 'M4.5 7.5L3 9C2.17157 9.82843 2.17157 11.1716 3 12C3.82843 12.8284 5.17157 12.8284 6 12L7.5 10.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p3',
          d: 'M8.5 5.5L10 4C10.8284 3.17157 12.1716 3.17157 13 4C13.8284 4.82843 13.8284 6.17157 13 7L11.5 8.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      ]);
    }

    // Trade type badge (BUY/SELL)
    function TradeTypeBadge({ tradeType }) {
      const badgeStyle = {
        display: 'inline-block',
        padding: '2px 6px',
        borderRadius: '4px',
        fontSize: '12px',
        fontWeight: '500',
        backgroundColor: tradeType === 'BUY' ? 'rgba(16, 185, 129, 0.1)' : 'rgba(239, 68, 68, 0.1)',
        color: tradeType === 'BUY' ? '#10b981' : '#ef4444'
      };

      return React.createElement('span', { style: badgeStyle }, tradeType);
    }

    // Payment methods component
    function PaymentMethods({ methods }) {
      if (!methods || methods.length === 0) return null;

      const containerStyle = {
        display: 'flex',
        flexWrap: 'wrap',
        gap: '4px',
        marginTop: '4px'
      };

      const methodStyle = {
        padding: '2px 6px',
        backgroundColor: '#f1f5f9',
        borderRadius: '4px',
        fontSize: '10px',
        color: '#64748b'
      };

      return React.createElement('div', { style: containerStyle },
        methods.map((method, index) => 
          React.createElement('span', { key: index, style: methodStyle }, method)
        )
      );
    }

    // Trader reputation component
    function TraderReputation({ trader }) {
      if (!trader) return null;

      const reputationColor = stringToColor(trader.nickname);

      const containerStyle = {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-end'
      };

      const nameStyle = {
        fontWeight: '500',
        fontSize: '12px',
        color: '#1e293b'
      };

      const statsStyle = {
        display: 'flex',
        alignItems: 'center',
        gap: '4px',
        fontSize: '11px',
        color: '#64748b'
      };

      const rateStyle = {
        padding: '1px 4px',
        borderRadius: '4px',
        backgroundColor: `${reputationColor}20`,
        color: reputationColor,
        fontWeight: '500'
      };

      return React.createElement('div', { style: containerStyle },
        React.createElement('span', { style: nameStyle }, trader.nickname),
        React.createElement('div', { style: statsStyle },
          React.createElement('span', { style: rateStyle }, `${trader.completion_rate}%`),
          React.createElement('span', {}, `${trader.orders_count} orders`)
        )
      );
    }

    // P2P Offer Card Component
    function P2POfferCard({ offer }) {
      const {
        trade_type,
        price,
        available_amount,
        min_amount,
        max_amount,
        payment_methods,
        trader,
        payment_timeout,
        metadata
      } = offer;

      const cardStyle = {
        position: 'relative',
        borderRadius: '8px',
        border: '1px solid #e2e8f0',
        backgroundColor: '#ffffff',
        padding: '8px 12px',
        marginBottom: '8px',
        width: '100%',
        boxSizing: 'border-box'
      };

      const flexContainerStyle = {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '8px'
      };

      const contentStyle = {
        minWidth: 0,
        flex: 1
      };

      const titleContainerStyle = {
        display: 'flex',
        alignItems: 'center',
        gap: '8px',
        marginBottom: '4px'
      };

      const priceStyle = {
        fontWeight: '600',
        color: '#1e293b',
        fontSize: '16px'
      };

      const subInfoStyle = {
        fontSize: '12px',
        color: '#64748b',
        display: 'flex',
        alignItems: 'center',
        gap: '8px'
      };

      const dividerStyle = {
        display: 'inline-block',
        width: '3px',
        height: '3px',
        borderRadius: '50%',
        backgroundColor: '#cbd5e1'
      };

      const formattedPrice = new Intl.NumberFormat('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }).format(price);

      const formattedAvailable = new Intl.NumberFormat('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }).format(available_amount);

      const formattedLimit = `${min_amount.toLocaleString()} - ${max_amount.toLocaleString()}`;

      return React.createElement('div', { style: cardStyle },
        React.createElement('div', { style: flexContainerStyle },
          React.createElement('div', { style: contentStyle },
            React.createElement('div', { style: titleContainerStyle },
              React.createElement(TradeTypeBadge, { tradeType: trade_type }),
              React.createElement('span', { style: priceStyle }, 
                `${formattedPrice} ${metadata.quote_currency}`
              )
            ),
            React.createElement('div', { style: subInfoStyle },
              React.createElement('span', {}, 
                `Available: ${formattedAvailable} ${metadata.base_currency}`
              ),
              React.createElement('span', { style: dividerStyle }),
              React.createElement('span', {}, 
                `Limit: ${formattedLimit} ${metadata.quote_currency}`
              ),
              React.createElement('span', { style: dividerStyle }),
              React.createElement('span', {}, 
                `${payment_timeout} min`
              )
            ),
            React.createElement(PaymentMethods, { methods: payment_methods })
          ),
          React.createElement(TraderReputation, { trader: trader })
        )
      );
    }

    // Render multiple offers
    const containerStyle = {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '12px',
      width: '100%'
    };

    const cardWrapperStyle = {
      width: 'calc(50% - 6px)', // Two cards per row with gap in between
      minWidth: '250px',
      boxSizing: 'border-box'
    };

    return React.createElement('div', { style: containerStyle },
      data.offers.map((offer, index) => 
        React.createElement('div', { 
          key: offer.order_id || index,
          style: cardWrapperStyle
        },
          React.createElement(P2POfferCard, { offer: offer })
        )
      )
    );
  }

  return BinanceP2POffersView(props);
}
